80	module	wbxbar #(
81			// i_sstall, i_sack, i_sdata, i_serr);
82			// {{{
83			parameter	NM = 4, NS=8,
84			parameter	AW = 32, DW=32,
85			parameter	[NS*AW-1:0]	SLAVE_ADDR = {
86					{ 3'b111, {(AW-3){1'b0}} },
87					{ 3'b110, {(AW-3){1'b0}} },
88					{ 3'b101, {(AW-3){1'b0}} },
89					{ 3'b100, {(AW-3){1'b0}} },
90					{ 3'b011, {(AW-3){1'b0}} },
91					{ 3'b010, {(AW-3){1'b0}} },
92					{ 4'b0010, {(AW-4){1'b0}} },
93					{ 4'b0000, {(AW-4){1'b0}} } },
94			parameter	[NS*AW-1:0]	SLAVE_MASK = (NS <= 1) ? 0
95				: { {(NS-2){ 3'b111, {(AW-3){1'b0}} }},
96					{(2){ 4'b1111, {(AW-4){1'b0}} }} },
97			//
98			// LGMAXBURST is the log_2 of the length of the longest burst
99			// that might be seen.  It's used to set the size of the
100			// internal counters that are used to make certain that the
101			// cross bar doesn't switch while still waiting on a response.
102			parameter	LGMAXBURST=6,
103			//
104			// OPT_TIMEOUT is used to help recover from a misbehaving slave.
105			// If set, this value will determine the number of clock cycles
106			// to wait for a misbehaving slave before returning a bus error.
107			// Alternatively, if set to zero, this functionality will be
108			// removed.
109			parameter	OPT_TIMEOUT = 0, // 1023;
110			//
111			// If OPT_TIMEOUT is set, then OPT_STARVATION_TIMEOUT may also
112			// be set.  The starvation timeout adds to the bus error timeout
113			// generation the possibility that a master will wait
114			// OPT_TIMEOUT counts without receiving the bus.  This may be
115			// the case, for example, if one bus master is consuming a
116			// peripheral to such an extent that there's no time/room for
117			// another bus master to use it.  In that case, when the timeout
118			// runs out, the waiting bus master will be given a bus error.
119			parameter [0:0]	OPT_STARVATION_TIMEOUT = 1'b0
120							&& (OPT_TIMEOUT > 0),
121			//
122			// OPT_DBLBUFFER is used to register all of the outputs, and
123			// thus avoid adding additional combinational latency through
124			// the core that might require a slower clock speed.
125			parameter [0:0]	OPT_DBLBUFFER = 1'b0,
126			//
127			// OPT_LOWPOWER adds logic to try to force unused values to
128			// zero, rather than to allow a variety of logic optimizations
129			// that could be used to reduce the logic count of the device.
130			// Hence, OPT_LOWPOWER will use more logic, but it won't drive
131			// bus wires unless there's a value to drive onto them.
132			parameter [0:0]	OPT_LOWPOWER = 1'b1
133			// }}}
134		) (
135			// {{{
136			input	wire			i_clk, i_reset,
137			//
138			// Here are the bus inputs from each of the WB bus masters
139			input	wire	[NM-1:0]	i_mcyc, i_mstb, i_mwe,
140			input	wire	[NM*AW-1:0]	i_maddr,
141			input	wire	[NM*DW-1:0]	i_mdata,
142			input	wire	[NM*DW/8-1:0]	i_msel,
143			//
144			// .... and their return data
145			output	wire	[NM-1:0]	o_mstall,
146			output	wire	[NM-1:0]	o_mack,
147			output	reg	[NM*DW-1:0]	o_mdata,
148			output	wire	[NM-1:0]	o_merr,
149			//
150			//
151			// Here are the output ports, used to control each of the
152			// various slave ports that we are connected to
153			output	reg	[NS-1:0]	o_scyc, o_sstb, o_swe,
154			output	reg	[NS*AW-1:0]	o_saddr,
155			output	reg	[NS*DW-1:0]	o_sdata,
156			output	reg	[NS*DW/8-1:0]	o_ssel,
157			//
158			// ... and their return data back to us.
159			input	wire	[NS-1:0]	i_sstall, i_sack,
160			input	wire	[NS*DW-1:0]	i_sdata,
161			input	wire	[NS-1:0]	i_serr
162			// }}}
163		);
164		//
165		//
166		////////////////////////////////////////////////////////////////////////
167		//
168		// Register declarations
169		// {{{
170		//
171		// TIMEOUT_WIDTH is the number of bits in counter used to check
172		// on a timeout.
173		localparam	TIMEOUT_WIDTH = $clog2(OPT_TIMEOUT);
174		//
175		// LGNM is the log (base two) of the number of bus masters
176		// connecting to this crossbar
177		localparam	LGNM = (NM>1) ? $clog2(NM) : 1;
178		//
179		// LGNS is the log (base two) of the number of slaves plus one
180		// come out of the system.  The extra "plus one" is used for a
181		// pseudo slave representing the case where the given address
182		// doesn't connect to any of the slaves.  This address will
183		// generate a bus error.
184		localparam	LGNS = $clog2(NS+1);
185		// At one time I used o_macc and o_sacc to put into the outgoing
186		// trace file, just enough logic to tell me if a transaction was
187		// taking place on the given clock.
188		//
189		// assign	o_macc = (i_mstb & ~o_mstall);
190		// assign	o_sacc = (o_sstb & ~i_sstall);
191		//
192		// These definitions work with Veri1ator, just not with Yosys
193		// reg	[NM-1:0][NS:0]		request;
194		// reg	[NM-1:0][NS-1:0]	requested;
195		// reg	[NM-1:0][NS:0]		grant;
196		//
197		// These definitions work with both
198		wire	[NS:0]			request		[0:NM-1];
199		reg	[NS-1:0]		requested	[0:NM-1];
200		reg	[NS:0]			grant		[0:NM-1];
201		reg	[NM-1:0]		mgrant;
202		reg	[NS-1:0]		sgrant;
203	
204		// Verilator lint_off UNUSED
205		wire	[LGMAXBURST-1:0]	w_mpending [0:NM-1];
206		// Verilator lint_on  UNUSED
207		reg	[NM-1:0]		mfull, mnearfull, mempty;
208		wire	[NM-1:0]		timed_out;
209	
210		localparam	NMFULL = (NM > 1) ? (1<<LGNM) : 1;
211		localparam	NSFULL = (1<<LGNS);
212	
213		wire	[LGNS-1:0]	mindex		[0:NMFULL-1];
214		wire	[LGNM-1:0]	sindex		[0:NSFULL-1];
215	
216		wire	[NMFULL-1:0]	m_cyc;
217		wire	[NMFULL-1:0]	m_stb;
218		wire	[NMFULL-1:0]	m_we;
219		wire	[AW-1:0]	m_addr		[0:NMFULL-1];
220		wire	[DW-1:0]	m_data		[0:NMFULL-1];
221		wire	[DW/8-1:0]	m_sel		[0:NMFULL-1];
222		reg	[NM-1:0]	m_stall;
223		//
224		wire	[NSFULL-1:0]	s_stall;
225		wire	[DW-1:0]	s_data		[0:NSFULL-1];
226		wire	[NSFULL-1:0]	s_ack;
227		wire	[NSFULL-1:0]	s_err;
228		wire	[NM-1:0]	dcd_stb;
229	
230		localparam [0:0]	OPT_BUFFER_DECODER=(NS != 1 || SLAVE_MASK != 0);
231		// }}}
232		////////////////////////////////////////////////////////////////////////
233		//
234		// Incoming signal arbitration
235		// {{{
236		////////////////////////////////////////////////////////////////////////
237		//
238		//
239	
240		genvar	N, M;
241		integer	iN, iM;
242		generate for(N=0; N<NM; N=N+1)
243		begin : DECODE_REQUEST
244			// {{{
245			// Register declarations
246			// {{{
247			wire			skd_stb, skd_stall;
248			wire			skd_we;
249			wire	[AW-1:0]	skd_addr;
250			wire	[DW-1:0]	skd_data;
251			wire	[DW/8-1:0]	skd_sel;
252			wire	[NS:0]		decoded;
253			wire			iskd_ready;
254			// }}}
255	
256			skidbuffer #(
257				// {{{
258				// Can't run OPT_LOWPOWER here, less we mess up the
259				// consistency in skd_we following
260				//
261				// .OPT_LOWPOWER(OPT_LOWPOWER),
262				.DW(1+AW+DW+DW/8),
263	`ifdef	FORMAL
264				.OPT_PASSTHROUGH(1),
265	`endif
266				.OPT_OUTREG(0)
267				// }}}
268			) iskid (
269				// {{{
270				.i_clk(i_clk),
271				.i_reset(i_reset || !i_mcyc[N]),
272				.i_valid(i_mstb[N]), .o_ready(iskd_ready),
273				.i_data({ i_mwe[N], i_maddr[N*AW +: AW],
274						i_mdata[N*DW +: DW],
275						i_msel[N*DW/8 +: DW/8] }),
276				.o_valid(skd_stb), .i_ready(!skd_stall),
277					.o_data({ skd_we, skd_addr, skd_data, skd_sel })
278				// }}}
279			);
280	
281			assign	o_mstall[N] = !iskd_ready;
282	
283			addrdecode #(
284				// {{{
285				// Can't run OPT_LOWPOWER here, less we mess up the
286				// consistency in m_we following
287				//
288				// .OPT_LOWPOWER(OPT_LOWPOWER),
289				.NS(NS), .AW(AW), .DW(DW+DW/8+1),
290				.SLAVE_ADDR(SLAVE_ADDR),
291				.SLAVE_MASK(SLAVE_MASK),
292				.OPT_REGISTERED(OPT_BUFFER_DECODER)
293				// }}}
294			) adcd(
295				// {{{
296				.i_clk(i_clk), .i_reset(i_reset),
297				.i_valid(skd_stb && i_mcyc[N]), .o_stall(skd_stall),
298					.i_addr(skd_addr),
299					.i_data({ skd_we, skd_data, skd_sel }),
300				.o_valid(dcd_stb[N]), .i_stall(m_stall[N]&&i_mcyc[N]),
301				.o_decode(decoded), .o_addr(m_addr[N]),
302					.o_data({ m_we[N], m_data[N], m_sel[N] })
303				// }}}
304			);
305	
306			assign	request[N] = (m_cyc[N] && dcd_stb[N]) ? decoded : 0;
307	
308			assign	m_cyc[N] = i_mcyc[N];
309			assign	m_stb[N] = i_mcyc[N] && dcd_stb[N] && !mfull[N];
310			// }}}
311		end for(N=NM; N<NMFULL; N=N+1)
312		begin : UNUSED_MASTER_SIGNALS
313			// {{{
314			// in case NM isn't one less than a power of two, complete
315			// the set
316			assign	m_cyc[N] = 0;
317			assign	m_stb[N] = 0;
318	
319			assign	m_we[N]   = 0;
320			assign	m_addr[N] = 0;
321			assign	m_data[N] = 0;
322			assign	m_sel[N]  = 0;
323			// }}}
324		end endgenerate
325	
326		// requested
327		// {{{
328		always @(*)
329		begin
330			for(iM=0; iM<NS; iM=iM+1)
331			begin
332				// For each slave
333				requested[0][iM] = 0;
334				for(iN=1; iN<NM; iN=iN+1)
335				begin
336					// This slave has been requested if a prior
337					// master has requested it
338					//
339					// This includes any master before the last one
340					requested[iN][iM] = requested[iN-1][iM];
341					//
342					// As well as if the last master has requested
343					// this slave.  Only count this request, though,
344					// if this master could act upon it.
345					if (request[iN-1][iM] &&
346						(grant[iN-1][iM]
347						|| (!mgrant[iN-1]||mempty[iN-1])))
348						requested[iN][iM] = 1;
349				end
350			end
351		end
352		// }}}
353	
354		generate for(M=0; M<NS; M=M+1)
355		begin : SLAVE_GRANT
356			// {{{
357	`define	REGISTERED_SGRANT
358	`ifdef	REGISTERED_SGRANT
359			// {{{
360			reg	drop_sgrant;
361	
362			// drop_sgrant
363			// {{{
364			always @(*)
365			begin
366				drop_sgrant = !m_cyc[sindex[M]];
367				if (!request[sindex[M]][M] && m_stb[sindex[M]]
368					&& mempty[sindex[M]])
369					drop_sgrant = 1;
370				if (!sgrant[M])
371					drop_sgrant = 0;
372				if (i_reset)
373					drop_sgrant = 1;
374			end
375			// }}}
376	
377			// sgrant
378			// {{{
379			initial	sgrant[M] = 0;
380			always @(posedge i_clk)
381			begin
382				sgrant[M] <= sgrant[M];
383				for(iN=0; iN<NM; iN=iN+1)
384				if (request[iN][M] && (!mgrant[iN] || mempty[iN]))
385					sgrant[M] <= 1;
386				if (drop_sgrant)
387					sgrant[M] <= 0;
388			end
389			// }}}
390			// }}}
391	`else
392			// {{{
393			// sgrant
394			// {{{
395			always @(*)
396			begin
397				sgrant[M] = 0;
398				for(iN=0; iN<NM; iN=iN+1)
399				if (grant[iN][M])
400					sgrant[M] = 1;
401			end
402			// }}}
403			// }}}
404	`endif
405	
406			assign	s_data[M]  = i_sdata[M*DW +: DW];
407			assign	s_stall[M] = o_sstb[M] && i_sstall[M];
408			assign	s_ack[M]   = o_scyc[M] && i_sack[M];
409			assign	s_err[M]   = o_scyc[M] && i_serr[M];
410	
411			// }}}
412		end for(M=NS; M<NSFULL; M=M+1)
413		begin : UNUSED_SLAVE_SIGNALS
414			// {{{
415			assign	s_data[M]  = 0;
416			assign	s_stall[M] = 1;
417			assign	s_ack[M]   = 0;
418			assign	s_err[M]   = 1;
419			// }}}
420		end endgenerate
421	
422		//
423		// Arbitrate among masters to determine who gets to access a given
424		// channel
425		generate for(N=0; N<NM; N=N+1)
426		begin : ARBITRATE_REQUESTS
427			// {{{
428	
429			// Register declarations
430			// {{{
431			wire	[NS:0]		regrant;
432			wire	[LGNS-1:0]	reindex;
433	
434			// This is done using a couple of variables.
435			//
436			// request[N][M]
437			//	This is true if master N is requesting to access slave
438			//	M.  It is combinatorial, so it will be true if the
439			//	request is being made on the current clock.
440			//
441			// requested[N][M]
442			//	True if some other master, prior to N, has requested
443			//	channel M.  This creates a basic priority arbiter,
444			//	such that lower numbered masters have access before
445			//	a greater numbered master
446			//
447			// grant[N][M]
448			//	True if a grant has been made for master N to access
449			//	slave channel M
450			//
451			// mgrant[N]
452			//	True if master N has been granted access to some slave
453			//	channel, any channel.
454			//
455			// mindex[N]
456			//	This is the number of the slave channel that master
457			//	N has been given access to
458			//
459			// sgrant[M]
460			//	True if there exists some master, N, that has been
461			// 	granted access to this slave, hence grant[N][M] must
462			//	also be true
463			//
464			// sindex[M]
465			//	This is the index of the master that has access to
466			//	slave M, assuming sgrant[M].  Hence, if sgrant[M]
467			//	then grant[sindex[M]][M] must be true
468			//
469			reg	stay_on_channel;
470			reg	requested_channel_is_available;
471			// }}}
472	
473			// stay_on_channel
474			// {{{
475			always @(*)
476			begin
477				stay_on_channel = |(request[N] & grant[N]);
478	
479				if (mgrant[N] && !mempty[N])
480					stay_on_channel = 1;
481			end
482			// }}}
483	
484			// requested_channel_is_available
485			// {{{
486			always @(*)
487			begin
488				requested_channel_is_available =
489				|(request[N][NS-1:0]& ~sgrant & ~requested[N][NS-1:0]);
490	
491				if (request[N][NS])
492					requested_channel_is_available = 1;
493	
494				if (NM < 2)
495					requested_channel_is_available = m_stb[N];
496			end
497			// }}}
498	
499			// grant, mgrant
500			// {{{
501			initial	grant[N] = 0;
502			initial	mgrant[N] = 0;
503			always @(posedge i_clk)
504			if (i_reset || !i_mcyc[N])
505			begin
506				grant[N] <= 0;
507				mgrant[N] <= 0;
508			end else if (!stay_on_channel)
509			begin
510				if (requested_channel_is_available)
511				begin
512					mgrant[N] <= 1'b1;
513					grant[N] <= request[N];
514				end else if (m_stb[N])
515				begin
516					mgrant[N] <= 1'b0;
517					grant[N]  <= 0;
518				end
519			end
520			// }}}
521	
522			if (NS == 1)
523			begin : MINDEX_ONE_SLAVE
524				// {{{
525				assign	mindex[N] = 0;
526				assign	regrant = 0;
527				assign	reindex = 0;
528				// }}}
529			end else begin : MINDEX_MULTIPLE_SLAVES
530				// {{{
531				reg	[LGNS-1:0]	r_mindex;
532	
533	`define	NEW_MINDEX_CODE
534	`ifdef	NEW_MINDEX_CODE
535				// {{{
536				reg	[NS:0]		r_regrant;
537				reg	[LGNS-1:0]	r_reindex;
538	
539				// r_regrant
540				// {{{
541				always @(*)
542				begin
543					r_regrant = 0;
544					for(iM=0; iM<NS; iM=iM+1)
545					begin
546						if (grant[N][iM])
547							// Maintain any open channels
548							r_regrant[iM] = 1'b1;
549						else if (!sgrant[iM]&&!requested[N][iM])
550							r_regrant[iM] = 1'b1;
551	
552						if (!request[N][iM])
553							r_regrant[iM] = 1'b0;
554					end
555	
556					if (grant[N][NS])
557						r_regrant[NS] = 1;
558					if (!request[N][NS])
559						r_regrant[NS] = 0;
560	
561					if (mgrant[N] && !mempty[N])
562						r_regrant = 0;
563				end
564				// }}}
565	
566				// r_reindex
567				// {{{
568				// Verilator lint_off BLKSEQ
569				always @(r_regrant, regrant)
570				begin
571					r_reindex = 0;
572					for(iM=0; iM<=NS; iM=iM+1)
573					if (r_regrant[iM])
574						r_reindex = r_reindex | iM[LGNS-1:0];
575					if (regrant == 0)
576						r_reindex = r_mindex;
577				end
578				// Verilator lint_on  BLKSEQ
579				// }}}
580	
581				always @(posedge i_clk)
582					r_mindex <= reindex;
583	
584				assign	reindex = r_reindex;
585				assign	regrant = r_regrant;
