591				begin
592	
593					for(iM=0; iM<NS; iM=iM+1)
594					begin
595						if (request[N][iM] && grant[N][iM])
596						begin
597							// Maintain any open channels
598							r_mindex <= iM;
599						end else if (request[N][iM]
600								&& !sgrant[iM]
601								&& !requested[N][iM])
602						begin
603							// Open a new channel
604							// if necessary
