623		// Calculate sindex.  sindex[M] (indexed by slave ID)
624		// references the master controlling this slave.  This makes for
625		// faster/cheaper logic on the return path, since we can now use
626		// a fully populated LUT rather than a priority based return scheme
627		generate for(M=0; M<NS; M=M+1)
628		begin : GEN_SINDEX
629			// {{{
630			if (NM <= 1)
631			begin : SINDEX_SINGLE_MASTER
632				// {{{
633				// If there will only ever be one master, then we
634				// can assume all slave indexes point to that master
635				assign	sindex[M] = 0;
636				// }}}
637			end else begin : SINDEX_MORE_THAN_ONE_MASTER
638				// {{{
639				reg	[LGNM-1:0]	r_sindex;
640	`define	NEW_SINDEX_CODE
641	`ifdef	NEW_SINDEX_CODE
642				// {{{
643				reg	[NM-1:0]	regrant;
644				reg	[LGNM-1:0]	reindex;
645	
646				always @(*)
647				begin
648					regrant = 0;
649					for (iN=0; iN<NM; iN=iN+1)
650					begin
651						// Each bit depends upon 6 inputs, so
652						// one 6-LUT should be sufficient
653						if (grant[iN][M])
654							regrant[iN] = 1;
655						else if (!sgrant[M]&& !requested[iN][M])
656							regrant[iN] = 1;
657	
658						if (!request[iN][M])
659							regrant[iN] = 0;
660						if (mgrant[iN] && !mempty[iN])
661							regrant[iN] = 0;
662					end
663				end
664	
665				always @(*)
666				begin
667					reindex = 0;
668					// Each bit in reindex depends upon all of the
669					// bits in regrant--should still be one LUT
670					// per bit though
671					if (regrant == 0)
672						reindex = sindex[M];
673					else for(iN=0; iN<NM; iN=iN+1)
674						if (regrant[iN])
675							reindex = reindex | iN[LGNM-1:0];
676				end
677	
678				always @(posedge i_clk)
679					r_sindex <= reindex;
680	
681				assign	sindex[M] = r_sindex;
682				// }}}
683	`else
684				// {{{
685				always @(posedge i_clk)
686				for (iN=0; iN<NM; iN=iN+1)
687				begin
688					if (!mgrant[iN] || mempty[iN])
689					begin
690						if (request[iN][M] && grant[iN][M])
691							r_sindex <= iN;
692						else if (request[iN][M] && !sgrant[M]
693								&& !requested[iN][M])
694							r_sindex <= iN;
695					end
696				end
697	
698				assign	sindex[M] = r_sindex;
699				// }}}
700	`endif
701				// }}}
702			end
703			// }}}
704		end for(M=NS; M<NSFULL; M=M+1)
705		begin : UNUSED_SINDEXES
706			// {{{
707			// Assign the unused slave indexes to zero
708			//
709			// Remember, to full out a full 2^something set of slaves,
710			// we may have more slave indexes than we actually have slaves
711	
712			assign	sindex[M] = 0;
713			// }}}
714		end endgenerate
