827					o_saddr[M*AW   +: AW] <= 0;
828					o_sdata[M*DW   +: DW] <= 0;
829					o_ssel[M*(DW/8)+:DW/8]<= 0;
830				end else if (!s_stall[M]) begin
831					o_swe[M]              <= m_we[sindex[M]];
832					o_saddr[M*AW   +: AW] <= m_addr[sindex[M]];
833					if (OPT_LOWPOWER && !m_we[sindex[M]])
834						o_sdata[M*DW   +: DW] <= 0;
835					else
