844		////////////////////////////////////////////////////////////////////////
845		//
846		// Assign return values to the masters
847		// {{{
848		////////////////////////////////////////////////////////////////////////
849		//
850		//
851		generate if (OPT_DBLBUFFER)
852		begin : DOUBLE_BUFFERRED_STALL
853			// {{{
854			reg	[NM-1:0]	r_mack, r_merr;
855	
856			for(N=0; N<NM; N=N+1)
857			begin : FOREACH_MASTER_PORT
858				// m_stall isn't buffered, since it depends upon
859				// the already existing buffer within the address
860				// decoder
861				always @(*)
862				begin
863					if (grant[N][NS])
864						m_stall[N] = 1;
865					else if (mgrant[N] && request[N][mindex[N]])
866						m_stall[N] = mfull[N] || s_stall[mindex[N]];
