997		//
998		// Count the pending transactions per master
999		generate for(N=0; N<NM; N=N+1)
1000		begin : COUNT_PENDING_TRANSACTIONS
1001			// {{{
1002			reg	[LGMAXBURST-1:0]	lclpending;
1003			initial	lclpending  = 0;
1004			initial	mempty[N]    = 1;
1005			initial	mnearfull[N] = 0;
1006			initial	mfull[N]     = 0;
1007			always @(posedge i_clk)
1008			if (i_reset || !i_mcyc[N] || o_merr[N])
1009			begin
1010				lclpending <= 0;
1011				mfull[N]    <= 0;
1012				mempty[N]   <= 1'b1;
1013				mnearfull[N]<= 0;
1014			end else case({ (m_stb[N] && !m_stall[N]), o_mack[N] })
1015			2'b01: begin
1016				lclpending <= lclpending - 1'b1;
1017				mnearfull[N]<= mfull[N];
1018				mfull[N]    <= 1'b0;
1019				mempty[N]   <= (lclpending == 1);
1020				end
1021			2'b10: begin
1022				lclpending <= lclpending + 1'b1;
1023				mnearfull[N]<= (&lclpending[LGMAXBURST-1:2])&&(lclpending[1:0] != 0);
1024				mfull[N]    <= mnearfull[N];
1025				mempty[N]   <= 1'b0;
