1191					assert(sgrant[M]);
1192					assert(sindex[M] == N);
1193				end
1194			end
1195			// }}}
1196		end endgenerate
1197	
1198		generate for(M=0; M<NS; M=M+1)
1199		begin : CHECK_SGRANT
1200			// {{{
1201			reg	f_sgrant;
1202	
1203			always @(*)
1204			if (sgrant[M])
1205				assert(grant[sindex[M]][M]);
1206	
1207			always @(*)
1208			begin
1209				f_sgrant = 0;
1210				for(iN=0; iN<NM; iN=iN+1)
1211				if (grant[iN][M])
1212					f_sgrant = 1;
1213			end
1214	
1215			always @(*)
1216				assert(sgrant[M] == f_sgrant);
1217			// }}}
1218		end endgenerate
1219	
1220		// Double check the timeout flags for consistency
1221		generate for(N=0; N<NM; N=N+1)
1222		begin : F_CHECK_TIMEOUT
1223			// {{{
1224			always @(*)
1225			if (f_past_valid)
1226			begin
1227				assert(mempty[N] == (w_mpending[N] == 0));
1228				assert(mnearfull[N]==(&w_mpending[N][LGMAXBURST-1:1]));
1229				assert(mfull[N] == (&w_mpending[N]));
1230			end
1231			// }}}
1232		end endgenerate
1233	
1234	`ifdef	VERIFIC
1235		// {{{
1236		// The Verific parser is currently broken, and doesn't allow
1237		// initial assumes or asserts.  The following lines get us around that
1238		//
1239		always @(*)
1240		if (!f_past_valid)
1241			assume(sgrant == 0);
1242	
1243		generate for(M=0; M<NS; M=M+1)
1244		begin
1245			always @(*)
1246			if (!f_past_valid)
1247			begin
1248				assume(o_scyc[M] == 0);
1249				assume(o_sstb[M] == 0);
1250				assume(sgrant[M] == 0);
1251			end
1252		end endgenerate
1253	
1254		generate for(N=0; N<NM; N=N+1)
1255		begin
1256			always @(*)
1257			if (!f_past_valid)
1258			begin
1259				assume(grant[N] == 0);
1260				assume(mgrant[N] == 0);
1261			end
1262		end endgenerate
1263		// }}}
1264	`endif
1265	
1266		////////////////////////////////////////////////////////////////////////
1267		//
1268		// BUS CHECK
1269		// {{{
1270		////////////////////////////////////////////////////////////////////////
1271		//
1272		//
1273		// Verify that every channel, whether master or slave, follows the rules
1274		// of the WB road.
1275		//
1276		generate for(N=0; N<NM; N=N+1)
1277		begin : WB_SLAVE_CHECK
1278			// {{{
1279			fwb_slave #(
1280				.AW(AW), .DW(DW),
1281				.F_LGDEPTH(LGMAXBURST),
1282				.F_MAX_ACK_DELAY(0),
1283				.F_MAX_STALL(0)
1284				) slvi(i_clk, i_reset,
1285					i_mcyc[N], i_mstb[N], i_mwe[N],
1286					i_maddr[N*AW +: AW], i_mdata[N*DW +: DW],
1287					i_msel[N*(DW/8) +: (DW/8)],
1288				o_mack[N], o_mstall[N], o_mdata[N*DW +: DW], o_merr[N],
1289				f_mreqs[N], f_macks[N], f_moutstanding[N]);
1290	
1291			always @(*)
1292			if ((f_past_valid)&&(grant[N][NS]))
1293				assert(f_moutstanding[N] <= 1);
1294	
1295			always @(*)
1296			if (f_past_valid && grant[N][NS] && i_mcyc[N])
1297				assert(m_stall[N] || o_merr[N]);
1298	
1299			always @(posedge i_clk)
1300			if (f_past_valid && $past(!i_reset && i_mstb[N] && o_mstall[N]))
1301				assume($stable(i_mdata[N*DW +: DW]));
1302			// }}}
1303		end endgenerate
1304	
1305		generate for(M=0; M<NS; M=M+1)
1306		begin : WB_MASTER_CHECK
1307			// {{{
1308			fwb_master #(
1309				.AW(AW), .DW(DW),
1310				.F_LGDEPTH(LGMAXBURST),
1311				.F_MAX_ACK_DELAY(F_MAX_DELAY),
1312				.F_MAX_STALL(2)
1313				) mstri(i_clk, i_reset,
1314					o_scyc[M], o_sstb[M], o_swe[M],
1315					o_saddr[M*AW +: AW], o_sdata[M*DW +: DW],
1316					o_ssel[M*(DW/8) +: (DW/8)],
1317				i_sack[M], i_sstall[M], s_data[M], i_serr[M],
1318				f_sreqs[M], f_sacks[M], f_soutstanding[M]);
1319			// }}}
1320		end endgenerate
1321		// }}}
1322		////////////////////////////////////////////////////////////////////////
1323		//
1324		// Correlate outstanding numbers
1325		// {{{
1326		////////////////////////////////////////////////////////////////////////
1327		//
1328		//
1329		generate for(N=0; N<NM; N=N+1)
1330		begin : CHECK_OUTSTANDING
1331			// {{{
1332			always @(*)
1333			if (mfull[N])
1334				assert(m_stall[N]);
1335	
1336			always @(posedge i_clk)
1337			if (i_mcyc[N])
1338				assert(f_moutstanding[N] == w_mpending[N]
1339					+((OPT_BUFFER_DECODER & dcd_stb[N]) ? 1:0));
1340	
1341			reg	[LGMAXBURST:0]	n_outstanding;
1342			always @(*)
1343			if (i_mcyc[N])
1344				assert(f_moutstanding[N] >=
1345					((OPT_BUFFER_DECODER && dcd_stb[N]) ? 1:0)
1346					+ (o_mack[N] && OPT_DBLBUFFER) ? 1:0);
1347	
1348			always @(*)
1349				n_outstanding = f_moutstanding[N]
1350					- ((OPT_BUFFER_DECODER && dcd_stb[N]) ? 1:0)
1351					- ((o_mack[N] && OPT_DBLBUFFER) ? 1:0);
1352	
1353			always @(posedge i_clk)
1354			if (i_mcyc[N] && !mgrant[N] && !o_merr[N])
1355				assert(f_moutstanding[N]
1356					== ((OPT_BUFFER_DECODER & dcd_stb[N]) ? 1:0));
1357	
1358			else if (i_mcyc[N] && mgrant[N] && !i_reset)
1359			for(iM=0; iM<NS; iM=iM+1)
1360			if (grant[N][iM] && o_scyc[iM] && !i_serr[iM] && !o_merr[N])
1361				assert(n_outstanding
1362					== {1'b0,f_soutstanding[iM]}
1363						+(o_sstb[iM] ? 1:0));
1364	
1365			always @(*)
1366			if (!i_reset)
1367			begin
1368				for(iM=0; iM<NS; iM=iM+1)
1369				if (grant[N][iM] && i_mcyc[N])
1370				begin
1371					if (f_soutstanding[iM] > 0)
1372						assert(i_mwe[N] == o_swe[iM]);
1373					if (o_sstb[iM])
1374						assert(i_mwe[N] == o_swe[iM]);
1375					if (o_mack[N])
1376						assert(i_mwe[N] == o_swe[iM]);
1377					if (o_scyc[iM] && i_sack[iM])
1378						assert(i_mwe[N] == o_swe[iM]);
1379					if (o_merr[N] && !timed_out[N])
1380						assert(i_mwe[N] == o_swe[iM]);
1381					if (o_scyc[iM] && i_serr[iM])
1382						assert(i_mwe[N] == o_swe[iM]);
1383				end
1384			end
1385	
1386			always @(*)
1387			if (!i_reset && OPT_BUFFER_DECODER && i_mcyc[N])
1388			begin
1389				if (dcd_stb[N])
1390					assert(i_mwe[N] == m_we[N]);
1391			end
1392			// }}}
1393		end endgenerate
1394	
1395		generate for(M=0; M<NS; M=M+1)
1396		begin : ASSERT_NOT_CYC_WO_GRANT
1397			// {{{
1398			always @(posedge i_clk)
1399			if (!$past(sgrant[M]))
1400				assert(!o_scyc[M]);
1401			// }}}
1402		end endgenerate
1403		// }}}
1404		////////////////////////////////////////////////////////////////////////
1405		//
1406		// CONTRACT SECTION
1407		// {{{
1408		////////////////////////////////////////////////////////////////////////
1409		//
1410		//
1411		// Here's the contract, in two parts:
1412		// {{{
1413		//	1. Should ever a master (any master) wish to read from a slave
1414		//		(any slave), he should be able to read a known value
1415		//		from that slave (any value) from any arbitrary address
1416		//		he might wish to read from (any address)
1417		//
1418		//	2. Should ever a master (any master) wish to write to a slave
1419		//		(any slave), he should be able to write the exact
1420		//		value he wants (any value) to the exact address he wants
1421		//		(any address)
1422		//
1423		//	special_master	is an arbitrary constant chosen by the solver,
1424		//		which can reference *any* possible master
1425		//	special_address	is an arbitrary constant chosen by the solver,
1426		//		which can reference *any* possible address the master
1427		//		might wish to access
1428		//	special_value	is an arbitrary value (at least during
1429		//		induction) representing the current value within the
1430		//		slave at the given address
1431		// }}}
1432		//
1433		////////////////////////////////////////////////////////////////////////
1434		//
1435		// Now let's pay attention to a special bus master and a special
1436		// address referencing a special bus slave.  We'd like to assert
1437		// that we can access the values of every slave from every master.
1438		(* anyconst *) reg	[(NM<=1)?0:(LGNM-1):0]	special_master;
1439				reg	[(NS<=1)?0:(LGNS-1):0]	special_slave;
1440		(* anyconst *) reg	[AW-1:0]	special_address;
1441				reg	[DW-1:0]	special_value;
1442	
1443		always @(*)
1444		if (NM <= 1)
1445			assume(special_master == 0);
1446		always @(*)
1447		if (NS <= 1)
1448			assume(special_slave == 0);
1449	
1450		//
1451		// Decode the special address to discover the slave associated with it
1452		always @(*)
1453		begin
1454			special_slave = NS;
1455			for(iM=0; iM<NS; iM = iM+1)
1456			begin
1457				if (((special_address ^ SLAVE_ADDR[iM*AW +: AW])
1458						&SLAVE_MASK[iM*AW +: AW]) == 0)
1459					special_slave = iM;
1460			end
1461		end
1462	
1463		generate if (NS > 1)
1464		begin : DOUBLE_ADDRESS_CHECK
1465			// {{{
1466			//
1467			// Check that no slave address has been assigned twice.
1468			// This check only needs to be done once at the beginning
1469			// of the run, during the BMC section.
1470			reg	address_found;
1471	
1472			always @(*)
1473			if (!f_past_valid)
1474			begin
1475				address_found = 0;
1476				for(iM=0; iM<NS; iM = iM+1)
1477				begin
1478					if (((special_address ^ SLAVE_ADDR[iM*AW +: AW])
1479							&SLAVE_MASK[iM*AW +: AW]) == 0)
1480					begin
1481						assert(address_found == 0);
1482						address_found = 1;
1483					end
1484				end
1485			end
1486			// }}}
1487		end endgenerate
1488		//
1489		// Let's assume this slave will acknowledge any request on the next
1490		// bus cycle after the stall goes low.  Further, lets assume that
1491		// it never creates an error, and that it always responds to our special
1492		// address with the special data value given above.  To do this, we'll
1493		// also need to make certain that the special value will change
1494		// following any write.
1495		//
1496		// These are the "assumptions" associated with our fictitious slave.
1497	`ifdef	VERIFIC
1498		always @(*)
1499		if (!f_past_valid)
1500			assume(special_value == 0);
1501	`else
1502		initial	assume(special_value == 0);
1503	`endif
1504		always @(posedge i_clk)
1505		if (special_slave < NS)
1506		begin
1507			// {{{
1508			if ($past(o_sstb[special_slave] && !i_sstall[special_slave]))
1509			begin
1510				assume(i_sack[special_slave]);
1511	
1512				if ($past(!o_swe[special_slave])
1513						&&($past(o_saddr[special_slave*AW +: AW]) == special_address))
1514					assume(i_sdata[special_slave*DW+: DW]
1515							== special_value);
1516			end else
1517				assume(!i_sack[special_slave]);
1518			assume(!i_serr[special_slave]);
1519	
1520			if (o_scyc[special_slave])
1521				assert(f_soutstanding[special_slave]
1522					== i_sack[special_slave]);
1523	
1524			if (o_sstb[special_slave] && !i_sstall[special_slave]
1525				&& o_swe[special_slave])
1526			begin
1527				for(iM=0; iM < DW/8; iM=iM+1)
1528				if (o_ssel[special_slave * DW/8 + iM])
1529					special_value[iM*8 +: 8] <= o_sdata[special_slave * DW + iM*8 +: 8];
1530			end
1531			// }}}
1532		end
1533	
1534		//
1535		// Now its time to make some assertions.  Specifically, we want to
1536		// assert that any time we read from this special slave, the special
1537		// value is returned.
1538		reg	[2:0]	f_read_seq;
1539		reg		f_read_ack, f_read_sstall;
1540	
1541		initial	f_read_sstall = 0;
1542		always @(posedge i_clk)
1543			f_read_sstall <= s_stall[special_slave];
1544	
1545		always @(*)
1546			f_read_ack = (f_read_seq[2] || ((!OPT_DBLBUFFER)&&f_read_seq[1]
1547						&& !f_read_sstall));
1548		initial	f_read_seq = 0;
1549		always @(posedge i_clk)
1550		if ((special_master < NM)&&(special_slave < NS)
1551				&&(i_mcyc[special_master])
1552				&&(!timed_out[special_master]))
1553		begin
1554			f_read_seq <= 0;
1555			if ((grant[special_master][special_slave])
1556				&&(m_stb[special_master])
1557				&&(m_addr[special_master] == special_address)
1558				&&(!m_we[special_master])
1559				)
1560			begin
1561				f_read_seq[0] <= 1;
1562			end
1563	
1564			if (|f_read_seq)
1565			begin
1566				assert(grant[special_master][special_slave]);
1567				assert(mgrant[special_master]);
1568				assert(sgrant[special_slave]);
1569				assert(mindex[special_master] == special_slave);
1570				assert(sindex[special_slave] == special_master);
1571				assert(!o_merr[special_master]);
1572			end
1573	
1574			if (f_read_seq[0] && !$past(s_stall[special_slave]))
1575			begin
1576				assert(o_scyc[special_slave]);
1577				assert(o_sstb[special_slave]);
1578				assert(!o_swe[special_slave]);
1579				assert(o_saddr[special_slave*AW +: AW] == special_address);
1580	
1581				f_read_seq[1] <= 1;
1582	
1583			end else if (f_read_seq[0] && $past(s_stall[special_slave]))
1584			begin
1585				assert($stable(m_stb[special_master]));
1586				assert(!m_we[special_master]);
1587				assert(m_addr[special_master] == special_address);
1588	
1589				f_read_seq[0] <= 1;
1590			end
1591	
1592			if (f_read_seq[1] && $past(s_stall[special_slave]))
1593			begin
1594				assert(o_scyc[special_slave]);
1595				assert(o_sstb[special_slave]);
1596				assert(!o_swe[special_slave]);
1597				assert(o_saddr[special_slave*AW +: AW] == special_address);
1598				f_read_seq[1] <= 1;
1599			end else if (f_read_seq[1] && !$past(s_stall[special_slave]))
1600			begin
1601				assert(i_sack[special_slave]);
1602				assert(i_sdata[special_slave*DW +: DW] == $past(special_value));
1603				if (OPT_DBLBUFFER)
1604					f_read_seq[2] <= 1;
1605			end
1606	
1607			if (f_read_ack)
1608			begin
1609				assert(o_mack[special_master]);
1610				assert(o_mdata[special_master * DW +: DW]
1611					== $past(special_value,2));
1612			end
1613		end else
1614			f_read_seq <= 0;
1615	
1616		always @(*)
1617			cover(i_mcyc[special_master] && f_read_ack);
1618	
1619		//
1620		// Let's try a write assertion now.  Specifically, on any request to
1621		// write to our special address, we want to assert that the special
1622		// value at that address can be written.
1623		reg	[2:0]	f_write_seq;
1624		reg		f_write_ack, f_write_sstall;
1625	
1626		initial	f_write_sstall = 0;
1627		always @(posedge i_clk)
1628			f_write_sstall = s_stall[special_slave];
1629	
1630		always @(*)
1631			f_write_ack = (f_write_seq[2]
1632					|| ((!OPT_DBLBUFFER)&&f_write_seq[1]
1633						&& !f_write_sstall));
1634		initial	f_write_seq = 0;
1635		always @(posedge i_clk)
1636		if ((special_master < NM)&&(special_slave < NS)
1637				&&(i_mcyc[special_master])
1638				&&(!timed_out[special_master]))
1639		begin
1640			f_write_seq <= 0;
1641			if ((grant[special_master][special_slave])
1642				&&(m_stb[special_master])
1643				&&(m_addr[special_master] == special_address)
1644				&&(m_we[special_master]))
1645			begin
1646				// Our write sequence begins when our special master
1647				// has access to the bus, *and* he is trying to write
1648				// to our special address.
1649				f_write_seq[0] <= 1;
1650			end
1651	
1652			if (|f_write_seq)
1653			begin
1654				assert(grant[special_master][special_slave]);
1655				assert(mgrant[special_master]);
1656				assert(sgrant[special_slave]);
1657				assert(mindex[special_master] == special_slave);
1658				assert(sindex[special_slave] == special_master);
1659				assert(!o_merr[special_master]);
1660			end
1661	
1662			if (f_write_seq[0] && !$past(s_stall[special_slave]))
1663			begin
1664				assert(o_scyc[special_slave]);
1665				assert(o_sstb[special_slave]);
1666				assert(o_swe[special_slave]);
1667				assert(o_saddr[special_slave*AW +: AW] == special_address);
1668				assert(o_sdata[special_slave*DW +: DW]
1669					== $past(m_data[special_master]));
1670				assert(o_ssel[special_slave*DW/8 +: DW/8]
1671					== $past(m_sel[special_master]));
1672	
1673				f_write_seq[1] <= 1;
1674	
1675			end else if (f_write_seq[0] && $past(s_stall[special_slave]))
1676			begin
1677				assert($stable(m_stb[special_master]));
1678				assert(m_we[special_master]);
1679				assert(m_addr[special_master] == special_address);
1680				assert($stable(m_data[special_master]));
1681				assert($stable(m_sel[special_master]));
1682	
1683				f_write_seq[0] <= 1;
1684			end
1685	
1686			if (f_write_seq[1] && $past(s_stall[special_slave]))
1687			begin
1688				assert(o_scyc[special_slave]);
1689				assert(o_sstb[special_slave]);
1690				assert(o_swe[special_slave]);
1691				assert(o_saddr[special_slave*AW +: AW] == special_address);
1692				assert($stable(o_sdata[special_slave*DW +: DW]));
1693				assert($stable(o_ssel[special_slave*DW/8 +: DW/8]));
1694				f_write_seq[1] <= 1;
1695			end else if (f_write_seq[1] && !$past(s_stall[special_slave]))
1696			begin
1697				for(iM=0; iM<DW/8; iM=iM+1)
1698				begin
1699					if ($past(o_ssel[special_slave * DW/8 + iM]))
1700						assert(special_value[iM*8 +: 8]
1701							== $past(o_sdata[special_slave*DW+iM*8 +: 8]));
1702				end
1703	
1704				assert(i_sack[special_slave]);
1705				if (OPT_DBLBUFFER)
1706					f_write_seq[2] <= 1;
1707			end
1708	
1709			if (f_write_seq[2] || ((!OPT_DBLBUFFER) && f_write_seq[1]
1710						&& !$past(s_stall[special_slave])))
1711				assert(o_mack[special_master]);
1712		end else
1713			f_write_seq <= 0;
1714	
1715		always @(*)
1716			cover(i_mcyc[special_master] && f_write_ack);
1717		// }}}
1718		////////////////////////////////////////////////////////////////////////
1719		//
1720		// COVER: Full connectivity check
1721		// {{{
1722		////////////////////////////////////////////////////////////////////////
1723		//
1724		//
1725		reg	[NM-1:0]	f_m_ackd;
1726		reg	[NS-1:0]	f_s_ackd;
1727		reg			f_cvr_aborted;
1728	
1729		initial	f_cvr_aborted = 0;
1730		always @(posedge i_clk)
1731		if (!f_past_valid || i_reset)
1732			f_cvr_aborted <= 0;
1733		else for(iN=0; iN<NM; iN=iN+1)
1734		begin
1735			if (request[iN][NS])
1736				f_cvr_aborted = 1;
1737			if ($fell(i_mcyc[iN]))
1738			begin
1739				if (f_macks[iN] != f_mreqs[iN])
1740					f_cvr_aborted = 1;
1741			end
1742		end
1743	
1744		initial	f_m_ackd = 0;
1745		generate for (N=0; N<NM; N=N+1)
1746		begin : GEN_FM_ACKD
1747	
1748			always @(posedge i_clk)
1749			if (i_reset)
1750				f_m_ackd[N] <= 0;
1751			else if (o_mack[N])
1752				f_m_ackd[N] <= 1'b1;
1753	
1754		end endgenerate
1755	
1756		always @(posedge i_clk)
1757			cover(!f_cvr_aborted && (&f_m_ackd));
1758	
1759		generate if (NM > 1)
1760		begin
1761	
1762			always @(posedge i_clk)
1763				cover(!f_cvr_aborted && (&f_m_ackd[1:0]));
1764	
1765		end endgenerate
1766	
1767		initial	f_s_ackd = 0;
1768		generate for (M=0; M<NS; M=M+1)
1769		begin : GEN_FS_ACKD
1770	
1771			always @(posedge i_clk)
1772			if (i_reset)
1773				f_s_ackd[M] <= 1'b0;
1774			else if (sgrant[M] && o_mack[sindex[M]])
1775				f_s_ackd[M] <= 1'b1;
1776	
1777		end endgenerate
1778	
1779		always @(posedge i_clk)
1780			cover(!f_cvr_aborted && (&f_s_ackd[NS-1:0]));
1781	
1782		generate if (NS > 1)
1783		begin
1784	
1785			always @(posedge i_clk)
1786				cover(!f_cvr_aborted && (&f_s_ackd[NS-1:0]));
1787	
1788		end endgenerate
1789		// }}}
1790	`endif
1791	// }}}
1792	endmodule
1793	`ifndef	YOSYS
1794	`default_nettype wire
1795	`endif
1796

